CREATE TABLE vane_audit(id TEXT PRIMARY KEY, at INTEGER NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, subject TEXT NOT NULL, detail TEXT NOT NULL);
CREATE INDEX vane_audit_at ON vane_audit(at);
-- Every native, review, OIDC, password or dev session is a sign-in, whichever door created it.
CREATE TRIGGER vane_audit_sign_in AFTER INSERT ON oa_sessions BEGIN
 INSERT INTO vane_audit(id,at,actor,action,subject,detail) VALUES(lower(hex(randomblob(16))),NEW.created_at,NEW.operator_id,'sign-in',NEW.operator_id,NEW.kind||' session');
END;

ALTER TABLE vane_events ADD COLUMN visitor TEXT;
-- One random salt per site and local day. It never leaves the database: the archive excludes it.
CREATE TABLE vane_salts(site_id TEXT NOT NULL, day TEXT NOT NULL, salt TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(site_id,day));

-- METRIC-002/003: when a page load was admitted, and its latest engagement ping (both epoch ms).
-- Events collected before this release, imports and demo rows without a time are left out of visits.
ALTER TABLE vane_events ADD COLUMN at INTEGER;
ALTER TABLE vane_events ADD COLUMN engaged_at INTEGER;

-- DASH-006: classes derived from the user agent and viewport width at collection; the user agent itself is never stored.
ALTER TABLE vane_events ADD COLUMN device TEXT;
ALTER TABLE vane_events ADD COLUMN browser TEXT;
ALTER TABLE vane_events ADD COLUMN browser_version TEXT;
ALTER TABLE vane_events ADD COLUMN os TEXT;
ALTER TABLE vane_events ADD COLUMN os_version TEXT;
ALTER TABLE vane_events ADD COLUMN screen TEXT;

-- DASH-012: the site-search term of a page load, when the owner names a search parameter. An empty
-- string records a search whose term looked personal (an email address, phone number or long number) and was dropped.
ALTER TABLE vane_events ADD COLUMN search TEXT;

-- CONV-003: automatic outbound-link, download, 404 and form-submission events, each with one recorded detail.
CREATE TABLE vane_auto_events(id TEXT PRIMARY KEY, site_id TEXT NOT NULL, day TEXT NOT NULL, kind TEXT NOT NULL, prop TEXT NOT NULL, at INTEGER NOT NULL);
CREATE INDEX vane_auto_events_site_day ON vane_auto_events(site_id, day);

-- COLLECT-002: the page's hostname (lowercased, no port), the UTM fields beyond the campaign, the paid-click flag
-- (set by gclid, fbclid or msclkid, whose values are never stored) and the owner's kept query parameters.
ALTER TABLE vane_events ADD COLUMN hostname TEXT;
ALTER TABLE vane_events ADD COLUMN utm_source TEXT;
ALTER TABLE vane_events ADD COLUMN utm_medium TEXT;
ALTER TABLE vane_events ADD COLUMN utm_term TEXT;
ALTER TABLE vane_events ADD COLUMN utm_content TEXT;
ALTER TABLE vane_events ADD COLUMN paid_click INTEGER;
ALTER TABLE vane_events ADD COLUMN query TEXT;

-- DASH-004: the channel derived at collection, and the referring page (hostname and redacted path, no query).
ALTER TABLE vane_events ADD COLUMN channel TEXT;
ALTER TABLE vane_events ADD COLUMN referrer TEXT;

-- COVERAGE-001: field-free daily counts of page loads that reached Vane but were not collected, by reason:
-- consent-declined (only when the owner turns the counter on) and excluded-path.
CREATE TABLE vane_exclusions(site_id TEXT NOT NULL, day TEXT NOT NULL, reason TEXT NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(site_id,day,reason));

-- DASH-009: dated chart annotations a site keeps: team members' notes and the events integrations post
-- (deploys, releases, incidents, error spikes, campaign sends). Settings changes, definition versions and imports
-- are annotated from the audit trail, the site's definitions and import approvals, so they are not copied here.
CREATE TABLE vane_annotations(id TEXT PRIMARY KEY, site_id TEXT NOT NULL, day TEXT NOT NULL, kind TEXT NOT NULL, text TEXT NOT NULL, url TEXT, author TEXT, at INTEGER NOT NULL);
CREATE INDEX vane_annotations_site_day ON vane_annotations(site_id,day);
-- The site's annotation webhook secret, created and revoked only by the owner; only its SHA-256 is kept.
CREATE TABLE vane_annotation_hooks(site_id TEXT PRIMARY KEY, secret_hash TEXT NOT NULL, created_at INTEGER NOT NULL, created_by TEXT NOT NULL);
-- The site's GitHub release key: HMAC verification needs the key itself, so it is kept encrypted (AES-GCM under a key
-- derived from the installation's session secret), created and revoked only by the owner, and accepts release events only.
CREATE TABLE vane_github_keys(site_id TEXT PRIMARY KEY, sealed_key TEXT NOT NULL, created_at INTEGER NOT NULL, created_by TEXT NOT NULL);

-- PERF-001: a page load's Core Web Vitals and load time, as the script last reported them: largest contentful paint,
-- interaction to next paint and load time in milliseconds, cumulative layout shift as a unitless score.
ALTER TABLE vane_events ADD COLUMN lcp INTEGER;
ALTER TABLE vane_events ADD COLUMN inp INTEGER;
ALTER TABLE vane_events ADD COLUMN cls REAL;
ALTER TABLE vane_events ADD COLUMN load_ms INTEGER;

-- DASH-007: a site's saved segments, named filter sets shared with its team; filters_json is a JSON array of
-- {dimension, op, value}. The owner and administrators save, replace and delete them.
CREATE TABLE vane_segments(id TEXT PRIMARY KEY, site_id TEXT NOT NULL, name TEXT NOT NULL, filters_json TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(site_id,name));

-- CONV-002: custom events, each on the page load it happened on (its visitor and visit come from that page load), and
-- the properties of custom events and pageviews (event_id is a custom event or a pageview), with their site and day.
CREATE TABLE vane_custom_events(id TEXT PRIMARY KEY, site_id TEXT NOT NULL, day TEXT NOT NULL, page_id TEXT NOT NULL, name TEXT NOT NULL, at INTEGER NOT NULL);
CREATE INDEX vane_custom_events_page ON vane_custom_events(page_id);
CREATE INDEX vane_custom_events_site_day ON vane_custom_events(site_id,day);
CREATE TABLE vane_event_props(event_id TEXT NOT NULL, site_id TEXT NOT NULL, day TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY(event_id,key));
CREATE INDEX vane_event_props_site_key ON vane_event_props(site_id,key,day);

-- CONV-007: the product lines of the standard ecommerce events (product view, add to cart, begin checkout, purchase),
-- each with the custom event it belongs to, its site and day; prices in the currency's minor units.
CREATE TABLE vane_ecommerce_lines(event_id TEXT NOT NULL, site_id TEXT NOT NULL, day TEXT NOT NULL, line INTEGER NOT NULL, sku TEXT NOT NULL, name TEXT NOT NULL, category TEXT, quantity INTEGER NOT NULL, price_minor INTEGER NOT NULL, currency TEXT NOT NULL, PRIMARY KEY(event_id,line));
CREATE INDEX vane_ecommerce_lines_site_day ON vane_ecommerce_lines(site_id,day);

-- CONV-006: a custom event's revenue, in millionths of the currency it was sent in (exact at its minor units).
ALTER TABLE vane_custom_events ADD COLUMN revenue_micros INTEGER;
ALTER TABLE vane_custom_events ADD COLUMN currency TEXT;

-- EXPERIMENT-001: one exposure per page load and experiment: the variant the page load's visitor hash was assigned
-- and applied there (its visitor and day come from that page load).
CREATE TABLE vane_exposures(page_id TEXT NOT NULL, site_id TEXT NOT NULL, day TEXT NOT NULL, experiment TEXT NOT NULL, variant TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY(page_id,experiment));
CREATE INDEX vane_exposures_site_day ON vane_exposures(site_id,experiment,day);

-- SHARE-001: read-only shared links to a site or one of its saved segments, with the reports the owner chose. Only the
-- SHA-256 of the link's token is kept; an optional password is kept as a salted PBKDF2-SHA256 hash. A revoked link's
-- row is deleted, so it answers 404 at once. failures/failed_from count wrong passwords in the current 15-minute window.
CREATE TABLE vane_share_links(id TEXT PRIMARY KEY, site_id TEXT NOT NULL, label TEXT NOT NULL, segment_id TEXT, reports_json TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, password_salt TEXT, password_hash TEXT, expires_at INTEGER, embed_origins_json TEXT NOT NULL, failures INTEGER NOT NULL DEFAULT 0, failed_from INTEGER, created_by TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX vane_share_links_site ON vane_share_links(site_id);

-- API-001: Stats API keys (read-only, for the sites in site_ids) and the owner's provisioning keys (site_ids NULL).
-- Only the SHA-256 of a key is kept; revoked_at refuses it at once. vane_api_usage counts requests per key in the
-- 10-second (scope b) and clock-hour (scope h) windows the published rate limits use, and per UTC day (scope d)
-- as the key's only record of its use.
CREATE TABLE vane_api_keys(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('stats','provisioning')), label TEXT NOT NULL, site_ids TEXT, token_hash TEXT NOT NULL UNIQUE, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, revoked_at INTEGER);
CREATE TABLE vane_api_usage(key_id TEXT NOT NULL, scope TEXT NOT NULL, window INTEGER NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(key_id,scope,window));

-- API-002: a site's scheduled warehouse export to an owner-entered S3-compatible bucket (Amazon S3 or Cloudflare R2).
-- The secret access key is sealed with AES-GCM under the installation's session secret and never shown again;
-- last_day is the last site-local date exported, next_attempt_at holds a failed run back for an hour, and
-- last_result is the newest run's outcome (counts or the refusal), as the audit records each run.
CREATE TABLE vane_exports(site_id TEXT PRIMARY KEY, endpoint TEXT NOT NULL, bucket TEXT NOT NULL, region TEXT NOT NULL, prefix TEXT NOT NULL, access_key_id TEXT NOT NULL, sealed_secret TEXT NOT NULL, last_day TEXT NOT NULL, next_attempt_at INTEGER, last_result TEXT, created_by TEXT NOT NULL, created_at INTEGER NOT NULL);

-- INSTALL-008: per-site events tokens (kind 'events', one site in site_ids) join the API keys, so the kind check is
-- rebuilt. vane_idempotency keeps only the SHA-256 of each Idempotency-Key a token sent in the last 24 hours, with
-- the counts its first request answered.
CREATE TABLE vane_api_keys_next(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('stats','provisioning','events')), label TEXT NOT NULL, site_ids TEXT, token_hash TEXT NOT NULL UNIQUE, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, revoked_at INTEGER);
INSERT INTO vane_api_keys_next(id,kind,label,site_ids,token_hash,created_by,created_at,revoked_at) SELECT id,kind,label,site_ids,token_hash,created_by,created_at,revoked_at FROM vane_api_keys;
DROP TABLE vane_api_keys;
ALTER TABLE vane_api_keys_next RENAME TO vane_api_keys;
CREATE TABLE vane_idempotency(key_id TEXT NOT NULL, key_hash TEXT NOT NULL, at INTEGER NOT NULL, answer TEXT, PRIMARY KEY(key_id,key_hash));

-- API-003: a site's signed webhooks. The signing secret is sealed (HMAC needs it); last_minute is the last ended UTC
-- minute whose goal conversions were queued. Each delivery keeps its counts-only payload, and each attempt only its
-- time, HTTP status and outcome.
CREATE TABLE vane_webhooks(id TEXT PRIMARY KEY, site_id TEXT NOT NULL, url TEXT NOT NULL, events_json TEXT NOT NULL, sealed_secret TEXT NOT NULL, last_minute INTEGER NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE vane_webhook_deliveries(id TEXT PRIMARY KEY, webhook_id TEXT NOT NULL, site_id TEXT NOT NULL, event TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','delivered','failed')), attempts INTEGER NOT NULL, next_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX vane_webhook_due ON vane_webhook_deliveries(state,next_at);
CREATE TABLE vane_webhook_attempts(delivery_id TEXT NOT NULL, attempt INTEGER NOT NULL, site_id TEXT NOT NULL, at INTEGER NOT NULL, status INTEGER, outcome TEXT NOT NULL, PRIMARY KEY(delivery_id,attempt));

-- REPORT-001: email report subscriptions (a team member's own address, or an external recipient the owner adds) and
-- each scheduled send. A send's id is its delivery ID on every attempt; only the SHA-256 of a subscription's
-- unsubscribe token is kept.
CREATE TABLE vane_report_subscriptions(id TEXT PRIMARY KEY, site_id TEXT NOT NULL, segment_id TEXT, email TEXT NOT NULL, operator_id TEXT, frequency TEXT NOT NULL CHECK(frequency IN ('daily','weekly','monthly')), weekday INTEGER NOT NULL, hour INTEGER NOT NULL, token_hash TEXT NOT NULL UNIQUE, next_at INTEGER NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(site_id,email,frequency));
CREATE TABLE vane_report_sends(id TEXT PRIMARY KEY, subscription_id TEXT NOT NULL, site_id TEXT NOT NULL, email TEXT NOT NULL, period_from TEXT NOT NULL, period_to TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','sent','failed')), attempts INTEGER NOT NULL, next_at INTEGER NOT NULL, reason TEXT, created_at INTEGER NOT NULL, sent_at INTEGER);
CREATE INDEX vane_report_due ON vane_report_sends(state,next_at);

-- MOBILE-001: the installation's VAPID key pair (private key sealed) and each person's per-browser push subscriptions.
CREATE TABLE vane_push_keys(id TEXT PRIMARY KEY, public_key TEXT NOT NULL, sealed_private TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE vane_push_subscriptions(id TEXT PRIMARY KEY, operator_id TEXT NOT NULL, endpoint TEXT NOT NULL UNIQUE, p256dh TEXT NOT NULL, auth TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX vane_push_subscriptions_operator ON vane_push_subscriptions(operator_id);

-- ALERT-001: traffic alerts on a fixed threshold (current visitors, or visitors, visits or pageviews in the last 60 minutes),
-- each with its cool-down and creator, and the alert log: when a crossing was seen, whether it was sent or held, and why.
CREATE TABLE vane_alerts(id TEXT PRIMARY KEY, site_id TEXT NOT NULL, metric TEXT NOT NULL CHECK(metric IN ('current','visitors','visits','pageviews')), direction TEXT NOT NULL CHECK(direction IN ('above','below')), threshold INTEGER NOT NULL, cooldown_hours INTEGER NOT NULL, crossed INTEGER NOT NULL DEFAULT 0, last_sent_at INTEGER, created_by TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE vane_alert_log(id TEXT PRIMARY KEY, alert_id TEXT NOT NULL, site_id TEXT NOT NULL, metric TEXT NOT NULL, direction TEXT NOT NULL, threshold INTEGER NOT NULL, value INTEGER NOT NULL, seen_at INTEGER NOT NULL, sent_at INTEGER, outcome TEXT NOT NULL);
CREATE INDEX vane_alert_log_site ON vane_alert_log(site_id,seen_at);

-- ALERT-001: an alert fires on a fixed threshold or on an anomaly against the same weekday and hour in the 8 weeks
-- before; the newest local hour it judged; and the site's scheduled maintenance windows, one-off or weekly, inside which
-- a drop is held and logged, not sent.
ALTER TABLE vane_alerts ADD COLUMN condition TEXT NOT NULL DEFAULT 'threshold' CHECK(condition IN ('threshold','anomaly'));
ALTER TABLE vane_alerts ADD COLUMN judged_hour INTEGER;
ALTER TABLE vane_alert_log ADD COLUMN condition TEXT NOT NULL DEFAULT 'threshold';
CREATE TABLE vane_maintenance(id TEXT PRIMARY KEY, site_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('once','weekly')), weekday INTEGER, day TEXT, start_minute INTEGER NOT NULL, end_minute INTEGER NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL);

-- ALERT-001: each alert's recipients (people who can open its site, and whether the site's signed webhooks get it) and
-- its quiet hours, as local minutes in the site's time zone.
ALTER TABLE vane_alerts ADD COLUMN recipients_json TEXT NOT NULL DEFAULT '{"people":[],"webhooks":false}';
ALTER TABLE vane_alerts ADD COLUMN quiet_from INTEGER;
ALTER TABLE vane_alerts ADD COLUMN quiet_to INTEGER;

-- ALERT-001: the site's business calendar: days the business is closed, left out of alert and report baselines and not
-- judged against ordinary weeks.
CREATE TABLE vane_closed_days(site_id TEXT NOT NULL, day TEXT NOT NULL, label TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(site_id,day));

-- FOLLOW-001: each sent alert opens a follow-up item with a responsible person, its next action and due time in the
-- site's business hours; reminders and escalation follow the owner's policy; every change is kept in the item's history.
CREATE TABLE vane_follow_policy(site_id TEXT PRIMARY KEY, remind_hours INTEGER NOT NULL, escalate_hours INTEGER NOT NULL, second_id TEXT, start_hour INTEGER NOT NULL, end_hour INTEGER NOT NULL, ended INTEGER NOT NULL DEFAULT 0, updated_by TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE vane_follow_items(id TEXT PRIMARY KEY, site_id TEXT NOT NULL, alert_id TEXT NOT NULL, title TEXT NOT NULL, responsible TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('open','acknowledged','resolved')), next_action TEXT NOT NULL, due_at INTEGER NOT NULL, escalate_at INTEGER NOT NULL, reminded_at INTEGER, escalated_at INTEGER, outcome TEXT CHECK(outcome IS NULL OR outcome IN ('real-change','tracking-fault','expected','ignored')), resolved_by TEXT, resolved_at INTEGER, created_at INTEGER NOT NULL);
CREATE INDEX vane_follow_open ON vane_follow_items(state,due_at);
CREATE TABLE vane_follow_events(id TEXT PRIMARY KEY, item_id TEXT NOT NULL, site_id TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL, at INTEGER NOT NULL);

-- ALERT-002: alerts also watch goal conversions and the conversion rate, for every goal or one goal. The metric list
-- now lives in code (traffic-alerts.ts ALERT_METRICS), so the table is rebuilt without its metric CHECK, keeping rows.
CREATE TABLE vane_alerts_next(id TEXT PRIMARY KEY, site_id TEXT NOT NULL, metric TEXT NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('above','below')), threshold INTEGER NOT NULL, cooldown_hours INTEGER NOT NULL, crossed INTEGER NOT NULL DEFAULT 0, last_sent_at INTEGER, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, condition TEXT NOT NULL DEFAULT 'threshold' CHECK(condition IN ('threshold','anomaly')), judged_hour INTEGER, recipients_json TEXT NOT NULL DEFAULT '{"people":[],"webhooks":false}', quiet_from INTEGER, quiet_to INTEGER, segment_id TEXT, goal TEXT);
INSERT INTO vane_alerts_next(id,site_id,metric,direction,threshold,cooldown_hours,crossed,last_sent_at,created_by,created_at,condition,judged_hour,recipients_json,quiet_from,quiet_to,segment_id) SELECT id,site_id,metric,direction,threshold,cooldown_hours,crossed,last_sent_at,created_by,created_at,condition,judged_hour,recipients_json,quiet_from,quiet_to,segment_id FROM vane_alerts;
DROP TABLE vane_alerts;
ALTER TABLE vane_alerts_next RENAME TO vane_alerts;

-- IMPORT-005: source aggregates retain their own definitions and independent report grain.
-- Never fabricate visitor hashes or individual events from report totals.
CREATE TABLE vane_import_reports (
 id TEXT PRIMARY KEY, site_id TEXT NOT NULL, import_job TEXT NOT NULL,
 day TEXT NOT NULL, provider TEXT NOT NULL, report TEXT NOT NULL,
 dimensions_json TEXT NOT NULL, metrics_json TEXT NOT NULL, definitions_json TEXT NOT NULL
);
CREATE INDEX vane_import_reports_site_day ON vane_import_reports(site_id,day);

-- SEARCH-001. Connection credentials and OAuth transactions are installation-local secrets:
-- never archive, export or transfer vane_search_connections / vane_search_oauth_states.
CREATE TABLE vane_search_connections (
 site_id TEXT PRIMARY KEY REFERENCES vane_sites(id) ON DELETE CASCADE,
 generation TEXT NOT NULL, sealed_tokens TEXT NOT NULL,
 property TEXT, properties_json TEXT NOT NULL DEFAULT '[]',
 connected_by TEXT NOT NULL, connected_at INTEGER NOT NULL,
 last_sync INTEGER, next_sync INTEGER NOT NULL, last_error TEXT,
 lock_id TEXT, lock_until INTEGER
);
CREATE TABLE vane_search_oauth_states (
 state_hash TEXT PRIMARY KEY, site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 actor_id TEXT NOT NULL, session_hash TEXT NOT NULL,
 redirect_uri TEXT NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER
);
CREATE INDEX vane_search_oauth_expiry ON vane_search_oauth_states(expires_at);
-- A day points at a complete immutable snapshot. A failed or disconnected sync never publishes half a day.
CREATE TABLE vane_search_days (
 site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE, day TEXT NOT NULL,
 property TEXT NOT NULL, snapshot_id TEXT, status TEXT NOT NULL CHECK(status IN ('final','pending')),
 checked_at INTEGER NOT NULL, published_at INTEGER,
 PRIMARY KEY(site_id,day)
);
CREATE TABLE vane_search_rows (
 site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE, day TEXT NOT NULL,
 snapshot_id TEXT NOT NULL,
 grain TEXT NOT NULL CHECK(grain IN ('overall','query','page','query_page')),
 query TEXT NOT NULL DEFAULT '', page TEXT NOT NULL DEFAULT '', path TEXT NOT NULL DEFAULT '',
 clicks REAL NOT NULL, impressions REAL NOT NULL, ctr REAL NOT NULL, position REAL NOT NULL,
 PRIMARY KEY(site_id,day,snapshot_id,grain,query,page)
);
CREATE INDEX vane_search_rows_site_day ON vane_search_rows(site_id,day);

CREATE TABLE vane_chat_connections (
 id TEXT PRIMARY KEY, site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 provider TEXT NOT NULL CHECK(provider IN ('slack','teams','nook')), label TEXT NOT NULL,
 channel TEXT, sealed_secret TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE TABLE vane_chat_states (
 state_hash TEXT PRIMARY KEY, site_id TEXT NOT NULL, actor_id TEXT NOT NULL, session_hash TEXT NOT NULL,
 label TEXT NOT NULL, channel TEXT NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER
);
CREATE TABLE vane_chat_schedules (
 id TEXT PRIMARY KEY, site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 connection_id TEXT NOT NULL REFERENCES vane_chat_connections(id) ON DELETE CASCADE,
 segment_id TEXT, frequency TEXT NOT NULL, weekday INTEGER NOT NULL, hour INTEGER NOT NULL,
 next_at INTEGER NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE TABLE vane_chat_log (
 id TEXT PRIMARY KEY, site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 connection_id TEXT NOT NULL, provider TEXT NOT NULL, label TEXT NOT NULL, kind TEXT NOT NULL,
 period TEXT NOT NULL, at INTEGER NOT NULL, state TEXT NOT NULL, reason TEXT NOT NULL,
 UNIQUE(connection_id,kind,period)
);

-- DASH-005: location names from Cloudflare's request geolocation at collection; no IP address is ever stored.
ALTER TABLE vane_events ADD COLUMN country TEXT;
ALTER TABLE vane_events ADD COLUMN region TEXT;
ALTER TABLE vane_events ADD COLUMN city TEXT;
ALTER TABLE vane_events ADD COLUMN metro TEXT;

-- DASH-005: retain the edge code separately from the sourced display name.
ALTER TABLE vane_events RENAME COLUMN metro TO metro_code;
ALTER TABLE vane_events ADD COLUMN metro_name TEXT;

-- DASH-005 (ct ruling 20 Oct 2026 22:31Z): events keep only the US metro code. Names come from each site's
-- owner-approved metro-name table, a site setting holding no visitor data, and are looked up when a report, export or
-- API answer is made. Vane ships no code-to-name table.
ALTER TABLE vane_events DROP COLUMN metro_name;
CREATE TABLE vane_metro_names(site_id TEXT NOT NULL,metro_code TEXT NOT NULL CHECK(length(metro_code)=3),metro_name TEXT NOT NULL,PRIMARY KEY(site_id,metro_code));
CREATE TABLE vane_metro_tables(site_id TEXT PRIMARY KEY,label TEXT,public INTEGER NOT NULL DEFAULT 0,rows INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 0,prepared_by TEXT,approved_by TEXT,approved_at INTEGER);

-- IMPORT-007: cut-over policy travels with imported history, including settled site transfers.
CREATE TABLE vane_import_cutovers (
 site_id TEXT NOT NULL, job_id TEXT NOT NULL, day TEXT NOT NULL,
 PRIMARY KEY(site_id,job_id)
);

CREATE TABLE vane_import_sources(site_id TEXT NOT NULL, job_id TEXT NOT NULL, provider TEXT NOT NULL, PRIMARY KEY(site_id,job_id));
CREATE TABLE vane_import_day_choices(site_id TEXT NOT NULL, day TEXT NOT NULL, job_id TEXT NOT NULL, provider TEXT NOT NULL, precedence INTEGER NOT NULL, PRIMARY KEY(site_id,day,job_id));
CREATE INDEX vane_import_events_job_day ON vane_import_events(site_id,import_job,day);
CREATE INDEX vane_import_sources_provider ON vane_import_sources(site_id,provider,job_id);

-- METRIC-005: only site-scoped digests; the raw first-party identifier is never stored.
ALTER TABLE vane_events ADD COLUMN consented_visitor TEXT;
ALTER TABLE vane_events ADD COLUMN consented_created_at INTEGER;
ALTER TABLE vane_events ADD COLUMN consented_expires_at INTEGER;
CREATE INDEX vane_events_consented ON vane_events(site_id,consented_visitor,day) WHERE consented_visitor IS NOT NULL;

-- An immutable import approval can resume by job ID only under its reviewed site policy.
-- Older approvals keep using the existing sanitized-document review door.
ALTER TABLE vane_import_approvals ADD COLUMN policy_version INTEGER;
ALTER TABLE vane_import_approvals ADD COLUMN policy_json TEXT;

-- AGENCY-001: client grouping and public report branding, independent of native account custody.
CREATE TABLE vane_agency_clients(id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE vane_agency_sites(site_id TEXT PRIMARY KEY, client_id TEXT NOT NULL);
CREATE INDEX vane_agency_client_sites ON vane_agency_sites(client_id);
CREATE TABLE vane_agency_members(operator_id TEXT PRIMARY KEY, client_id TEXT NOT NULL);
CREATE TABLE vane_agency_brands(id TEXT PRIMARY KEY, name TEXT NOT NULL, accent TEXT NOT NULL, background TEXT NOT NULL, logo_id TEXT, custom_origin TEXT UNIQUE, enabled INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL);
CREATE TABLE vane_agency_logos(id TEXT PRIMARY KEY, brand_id TEXT NOT NULL, mime TEXT NOT NULL, bytes BLOB NOT NULL);

-- COLLECT-004: exact native whole-day occurrence cells and identity reference
-- counts. Compression depends on actual dimension/identity cardinality; this
-- never discards raw rows, approximates visitors, or answers visit metrics.
CREATE TABLE vane_analytics_cells(
 site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 day TEXT NOT NULL, kind TEXT NOT NULL, cell TEXT NOT NULL,
 n INTEGER NOT NULL CHECK(n>=0), timed INTEGER NOT NULL CHECK(timed>=0), consented INTEGER NOT NULL CHECK(consented>=0),
 PRIMARY KEY(site_id,day,kind,cell)
) WITHOUT ROWID;
CREATE TABLE vane_analytics_identities(
 site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 day TEXT NOT NULL, kind TEXT NOT NULL, cell TEXT NOT NULL, identity TEXT NOT NULL,
 n INTEGER NOT NULL CHECK(n>=0),
 PRIMARY KEY(site_id,day,kind,cell,identity)
) WITHOUT ROWID;
CREATE INDEX vane_analytics_identity_range ON vane_analytics_identities(site_id,day,kind,identity);

-- Existing native history is materialized in the migration transaction.
INSERT INTO vane_analytics_cells(site_id,day,kind,cell,n,timed,consented)
SELECT site_id,day,kind,json_array(path,source,campaign,hostname,device,browser,browser_version,os,os_version,screen,channel,referrer,utm_source,utm_medium,utm_term,utm_content,country,region,city,metro_code,search,transport,consent,sample_rate,import_job),COUNT(*),SUM(at IS NOT NULL),SUM(consented_visitor IS NOT NULL)
FROM vane_events GROUP BY site_id,day,kind,json_array(path,source,campaign,hostname,device,browser,browser_version,os,os_version,screen,channel,referrer,utm_source,utm_medium,utm_term,utm_content,country,region,city,metro_code,search,transport,consent,sample_rate,import_job);
INSERT INTO vane_analytics_identities(site_id,day,kind,cell,identity,n)
SELECT site_id,day,kind,json_array(path,source,campaign,hostname,device,browser,browser_version,os,os_version,screen,channel,referrer,utm_source,utm_medium,utm_term,utm_content,country,region,city,metro_code,search,transport,consent,sample_rate,import_job),CASE WHEN consented_visitor IS NOT NULL THEN site_id||' c '||consented_visitor ELSE site_id||' d '||day||' '||visitor END,COUNT(*)
