 first_raw=   CASE    WHEN ((SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT token FROM vane_visit_work WHERE raw_id=NEW.raw_id))<(started,(SELECT token FROM vane_raw_events WHERE raw_id=first_raw)) THEN NEW.raw_id ELSE first_raw    END   ,
 last_raw=   CASE    WHEN ((SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT token FROM vane_visit_work WHERE raw_id=NEW.raw_id))>(last_at,(SELECT token FROM vane_raw_events WHERE raw_id=last_raw)) THEN NEW.raw_id ELSE last_raw    END   ,
 started=MIN(started,(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)),last_at=MAX(last_at,(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)),last_signal=MAX(last_signal,(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id))),identity=MAX(identity,(SELECT identity FROM vane_visit_work WHERE raw_id=NEW.raw_id))
 WHERE visit=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id);
