CREATE TRIGGER vane_visit_detail_change AFTER INSERT ON vane_visit_work WHEN NEW.action='detail' BEGIN
 UPDATE vane_visit_work SET
 (site,context,day,visitor,site_id,at,at_offset,token,identity)=(
 SELECT e.site,e.context,c.day,c.visitor,s.site_id,e.at_offset+unixepoch(c.day)*1000,e.at_offset,e.token,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||(  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END  )
 ELSE s.site_id||' d '||c.day||' '||(  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END  )   END  
 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context
 JOIN vane_raw_sites s ON s.site=e.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor
 LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE e.raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET next=(SELECT (SELECT candidate.raw_id FROM vane_raw_contexts cx JOIN vane_raw_events candidate ON candidate.raw_id=COALESCE(
 (SELECT tied.raw_id FROM vane_raw_events tied
  WHERE tied.context=cx.context AND tied.at_offset=r.at_offset AND tied.token>r.token
  ORDER BY tied.token ASC LIMIT 1),
 (SELECT adjacent.raw_id FROM vane_raw_events adjacent
  WHERE adjacent.context=cx.context AND adjacent.at_offset=(
   SELECT bucket.at_offset FROM vane_raw_events bucket
   WHERE bucket.context=cx.context AND bucket.at_offset>r.at_offset
   ORDER BY bucket.at_offset ASC LIMIT 1)
  ORDER BY adjacent.token ASC LIMIT 1))
 WHERE cx.site=r.site AND cx.day=r.day AND cx.visitor=r.visitor AND cx.kind='pageview'
 ORDER BY candidate.at_offset ASC,candidate.token ASC LIMIT 1) FROM vane_visit_work r WHERE r.raw_id=NEW.raw_id),gap=(SELECT (COALESCE((SELECT json_extract(d.value,'$.minutes') FROM vane_sites s,json_each(s.config_json,'$.definitions') d WHERE s.id=r.site_id AND json_extract(d.value,'$.metric')='visit-timeout' AND json_extract(d.value,'$.from')<=r.day ORDER BY json_extract(d.value,'$.from') DESC,CAST(d.key AS INTEGER) DESC LIMIT 1),30)*60000) FROM vane_visit_work r WHERE r.raw_id=NEW.raw_id),visit=(SELECT visit_id FROM vane_raw_events WHERE raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET
 (prev_at,prev_context,prev_engaged,prev_scroll,prev_visit,next_at,next_visit)=(
 SELECT p.at_offset+unixepoch(pc.day)*1000,p.context,pd.engaged_at,pd.scroll,p.visit_id,
 n.at_offset+unixepoch(nc.day)*1000,n.visit_id
 FROM vane_visit_work w
 LEFT JOIN vane_raw_events p ON p.raw_id=w.prev
 LEFT JOIN vane_raw_contexts pc ON pc.context=p.context
 LEFT JOIN vane_raw_details pd ON pd.raw_id=p.raw_id
 LEFT JOIN vane_raw_events n ON n.raw_id=w.next
 LEFT JOIN vane_raw_contexts nc ON nc.context=n.context
 WHERE w.raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET old_on_page=   CASE    WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE(old_engaged-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)    END    WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_page_frequencies SET n=n-1 WHERE visit=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND context=(SELECT context FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND on_page=(SELECT old_on_page FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND scroll=COALESCE((SELECT old_scroll FROM vane_visit_work WHERE raw_id=NEW.raw_id),-1) AND 1;
 DELETE FROM vane_visit_page_frequencies WHERE visit=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND n=0;
 INSERT INTO vane_visit_page_frequencies(visit,context,on_page,scroll,n) SELECT (SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT context FROM vane_visit_work WHERE raw_id=NEW.raw_id),   CASE    WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)    END   ,COALESCE((SELECT new_scroll FROM vane_visit_work WHERE raw_id=NEW.raw_id),-1),1 WHERE 1
 ON CONFLICT(visit,context,on_page,scroll) DO UPDATE SET n=n+1;
 UPDATE vane_visit_facts SET engaged=engaged+((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL)-((SELECT old_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL),
 first_on_page=   CASE    WHEN first_raw=NEW.raw_id THEN    CASE    WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)    END    ELSE first_on_page    END   ,
 last_signal=   CASE    WHEN (SELECT old_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)=last_signal AND COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)<(SELECT old_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN
 (SELECT MAX(MAX((r.at_offset+unixepoch(signal_context.day)*1000),COALESCE(   CASE    WHEN r.raw_id=NEW.raw_id THEN (SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE signal_details.engaged_at    END   ,(r.at_offset+unixepoch(signal_context.day)*1000)))) FROM vane_raw_events r JOIN vane_raw_contexts signal_context ON signal_context.context=r.context LEFT JOIN vane_raw_details signal_details ON signal_details.raw_id=r.raw_id WHERE r.visit_id=vane_visit_facts.visit)
 ELSE MAX(last_signal,COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)))    END    WHERE visit=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id);
 DELETE FROM vane_visit_work WHERE raw_id=NEW.raw_id;
   END   ;

CREATE TRIGGER vane_visit_raw_delete BEFORE DELETE ON vane_raw_occurrences BEGIN
 INSERT OR IGNORE INTO vane_visit_dirty(site,day,visitor) SELECT site,day,visitor FROM vane_raw_contexts WHERE context=(SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id) AND kind='pageview' AND visitor IS NOT NULL;
