  END  ;

CREATE TRIGGER vane_visit_raw_rewrite BEFORE UPDATE OF group_id,site,token ON vane_raw_occurrences WHEN (SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id) IS NOT (SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) OR (SELECT at_offset FROM vane_raw_groups WHERE group_id=OLD.group_id) IS NOT (SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) OR OLD.site IS NOT NEW.site OR OLD.token IS NOT NEW.token BEGIN
 INSERT OR IGNORE INTO vane_visit_legacy(site,day,visitor)
 SELECT site,day,visitor FROM vane_raw_contexts WHERE context=(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id)
 AND kind='pageview' AND visitor IS NOT NULL AND typeof(NEW.token)!='blob';
 INSERT OR IGNORE INTO vane_visit_dirty(site,day,visitor) SELECT site,day,visitor FROM vane_raw_contexts WHERE context IN ((SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id),(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id)) AND kind='pageview' AND visitor IS NOT NULL;
  END  ;

