CREATE TRIGGER vane_raw_group_gc AFTER DELETE ON vane_raw_groups BEGIN
 DELETE FROM vane_raw_contexts WHERE context=OLD.context
 AND NOT EXISTS(SELECT 1 FROM vane_raw_groups WHERE context=OLD.context);
 END ;

-- Every occurrence in one raw context/time group has the same exact visit.
-- Queue one assignment per group; conflicting assignments must abort rather
-- than choosing an arbitrary visit. Cleared inside the admitting transaction.
CREATE TABLE vane_visit_bulk_membership(
 group_id INTEGER PRIMARY KEY,visit INTEGER NOT NULL
);

-- A timestamp group can contain many distinct page loads. Cover its full IDs
-- so exact canonical visit neighbors do not scan and sort that whole bucket.
CREATE INDEX vane_raw_occurrences_group_token ON vane_raw_occurrences(group_id,token);
DROP INDEX vane_raw_occurrences_group;

-- Keep every full token in the occurrence and its unique site/token index.
-- The journey index orders by a four-byte prefix; readers resolve every tie
-- using the full token, so even deliberately colliding prefixes stay exact.
CREATE INDEX vane_raw_occurrences_group_prefix ON vane_raw_occurrences(group_id,substr(token,1,4));
DROP INDEX vane_raw_occurrences_group_token;

-- Seek the next actual timestamp within one maintained visit without scanning
-- every metadata group in that visit. Membership and all occurrences remain
-- unchanged; the partial index still excludes groups without a visit.
DROP INDEX vane_raw_groups_visit;
CREATE INDEX vane_raw_groups_visit ON vane_raw_groups(visit_id,at_offset) WHERE visit_id IS NOT NULL;

CREATE TABLE vane_security_policy (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 require_sso INTEGER NOT NULL DEFAULT 0 CHECK(require_sso IN (0,1)),
 require_second INTEGER NOT NULL DEFAULT 0 CHECK(require_second IN (0,1))
);

-- Installation-local authenticator credentials. All timestamps are epoch milliseconds.
CREATE TABLE vane_totp_credentials (
 operator_id TEXT PRIMARY KEY REFERENCES oa_operators(id) ON DELETE CASCADE,
 secret_sealed TEXT NOT NULL,
 last_step INTEGER NOT NULL,
 created_at INTEGER NOT NULL
);
CREATE TABLE vane_totp_pending (
 operator_id TEXT PRIMARY KEY REFERENCES oa_operators(id) ON DELETE CASCADE,
 session_id TEXT NOT NULL,
 secret_sealed TEXT NOT NULL,
 expires_at INTEGER NOT NULL
);
CREATE TABLE vane_totp_recovery (
 operator_id TEXT NOT NULL REFERENCES vane_totp_credentials(operator_id) ON DELETE CASCADE,
 code_hash TEXT NOT NULL,
 PRIMARY KEY(operator_id,code_hash)
);
-- Keep only the current aligned window per operator/session, rather than one row per guess.
CREATE TABLE vane_second_step_attempts (
 scope TEXT NOT NULL CHECK(scope IN ('operator','session')),
 subject TEXT NOT NULL,
 window INTEGER NOT NULL,
 count INTEGER NOT NULL CHECK(count BETWEEN 1 AND 5),
 PRIMARY KEY(scope,subject)
);
-- Deliberately no session FK: the native auth migrations may rebuild oa_sessions.
-- Admission must still join the current, unrevoked session and operator version.
CREATE TABLE vane_second_step_sessions (
 session_id TEXT PRIMARY KEY,
 operator_id TEXT NOT NULL REFERENCES oa_operators(id) ON DELETE CASCADE,
 verified_at INTEGER NOT NULL
);

-- TEAM-002: short-lived SP-initiated SAML attempts. Both the browser/RelayState
-- claim and the library's request cache live in D1, never process memory.
CREATE TABLE vane_saml_requests (
 relay_hash TEXT PRIMARY KEY, browser_hash TEXT NOT NULL,
 config_hash TEXT NOT NULL, request_id TEXT NOT NULL UNIQUE,
 request_value TEXT NOT NULL, created_at INTEGER NOT NULL,
 expires_at INTEGER NOT NULL, claim TEXT, cache_removed INTEGER NOT NULL DEFAULT 0 CHECK(cache_removed IN (0,1))
);
CREATE INDEX vane_saml_expiry ON vane_saml_requests(expires_at);
CREATE INDEX vane_saml_browser ON vane_saml_requests(browser_hash,expires_at);

-- SCIM records associations to an invitation the owner already authorized.
-- Provisioning never creates a person, changes a grant, or accepts an invitation.
CREATE TABLE vane_scim_users (
 operator_id TEXT PRIMARY KEY REFERENCES oa_operators(id),
 external_id TEXT UNIQUE, created_at INTEGER NOT NULL
);

-- Owner-issued SCIM authority is scoped to one exact federation issuer. Only a
-- digest is stored; replacement immediately invalidates the preceding bearer.
CREATE TABLE vane_scim_credentials (
 issuer TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE,
 created_by TEXT NOT NULL REFERENCES oa_operators(id), created_at INTEGER NOT NULL,
 revoked_at INTEGER
);

-- An old association recorded no issuer, so it cannot authorize federation.
-- Keep it as an inaccessible tombstone rather than infer authority from email.
ALTER TABLE vane_scim_users RENAME TO vane_scim_users_legacy;
CREATE TABLE vane_scim_users (
 operator_id TEXT PRIMARY KEY REFERENCES oa_operators(id),
 issuer TEXT NOT NULL, external_id TEXT, created_at INTEGER NOT NULL,
 deactivated_at INTEGER, transition_id TEXT,
 UNIQUE(issuer,external_id)
);
INSERT INTO vane_scim_users(operator_id,issuer,external_id,created_at,deactivated_at)
 SELECT operator_id,'',external_id,created_at,created_at FROM vane_scim_users_legacy;
DROP TABLE vane_scim_users_legacy;

-- Native admission may establish ordinary accounts from a verified email. A
-- SCIM-managed person instead has exactly the binding the owner authorized.
CREATE TRIGGER vane_scim_fixed_federation BEFORE INSERT ON oa_external_identities
 WHEN EXISTS(SELECT 1 FROM vane_scim_users s WHERE s.operator_id=NEW.operator_id
 AND (s.issuer!=NEW.issuer OR s.external_id IS NOT NEW.subject))
 BEGIN SELECT RAISE(IGNORE); END;

-- Owner removal is durable even if an older provision request arrives later.
CREATE TRIGGER vane_scim_owner_removal AFTER UPDATE OF status ON oa_operators
 WHEN NEW.status='inactive' AND OLD.status!='inactive'
 BEGIN UPDATE vane_scim_users SET deactivated_at=COALESCE(deactivated_at,CAST(strftime('%s','now') AS INTEGER)*1000),
 transition_id=COALESCE(transition_id,lower(hex(randomblob(16)))) WHERE operator_id=NEW.id; END;

-- Derived investigations and reviewed fix drafts. No source bodies or visitor fields are copied here.
CREATE TABLE vane_instrumentation_runs (
 id TEXT PRIMARY KEY, site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 actor_id TEXT NOT NULL, at INTEGER NOT NULL, scan_id TEXT NOT NULL,
 from_day TEXT NOT NULL, to_day TEXT NOT NULL, report_json TEXT NOT NULL
);
CREATE INDEX vane_instrumentation_runs_site ON vane_instrumentation_runs(site_id,at);
CREATE TABLE vane_instrumentation_fixes (
 id TEXT PRIMARY KEY, site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 run_id TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL,
 proposal_id TEXT NOT NULL, draft_json TEXT NOT NULL, verified_at INTEGER
);
CREATE INDEX vane_instrumentation_fixes_site ON vane_instrumentation_fixes(site_id,created_at);

-- Off-default, owner-approved incoming aggregates. The sender key grants no native/API/annotation authority.
CREATE TABLE vane_agent_evidence_keys (
 site_id TEXT PRIMARY KEY REFERENCES vane_sites(id) ON DELETE CASCADE,
 secret_hash TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL,
 window_start INTEGER NOT NULL DEFAULT 0, requests INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE vane_agent_evidence (
 site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 day TEXT NOT NULL, metric TEXT NOT NULL CHECK(metric IN ('orders','checkout-errors','uptime-failures')),
 numerator INTEGER NOT NULL CHECK(numerator>=0), denominator INTEGER NOT NULL CHECK(denominator>=numerator),
 revision INTEGER NOT NULL CHECK(revision>0), content_hash TEXT NOT NULL,
 url TEXT, received_at INTEGER NOT NULL,
 PRIMARY KEY(site_id,day,metric)
);
CREATE TABLE vane_movement_investigations (
 id TEXT PRIMARY KEY, site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 actor_id TEXT NOT NULL, at INTEGER NOT NULL, from_day TEXT NOT NULL, to_day TEXT NOT NULL,
 compared_from TEXT NOT NULL, compared_to TEXT NOT NULL, report_json TEXT NOT NULL
);
CREATE INDEX vane_movement_investigations_site ON vane_movement_investigations(site_id,at);

-- Anonymous page geometry, never DOM text, attributes, selectors or identifiers.
CREATE TABLE vane_heat_layouts (
 site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 day TEXT NOT NULL,
 path TEXT NOT NULL,
 width INTEGER NOT NULL,
 geometry_json TEXT NOT NULL,
 PRIMARY KEY(site_id,day,path,width)
);
CREATE TRIGGER vane_heat_layout_erasure AFTER INSERT ON vane_deletions BEGIN
 DELETE FROM vane_heat_layouts WHERE site_id=NEW.site_id AND day<NEW.before_day;
END;

CREATE TABLE vane_agent_work (
 id TEXT PRIMARY KEY, site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 kind TEXT NOT NULL, from_day TEXT NOT NULL, to_day TEXT NOT NULL,
 payload_json TEXT NOT NULL, created_by TEXT NOT NULL, at INTEGER NOT NULL
);
CREATE INDEX vane_agent_work_site ON vane_agent_work(site_id,kind,from_day,to_day);
CREATE TABLE vane_agent_dismissals (
 site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 type TEXT NOT NULL, actor TEXT NOT NULL, at INTEGER NOT NULL,
 PRIMARY KEY(site_id,type)
);

-- Installation-local GA4 credentials and single-use approvals. Never archived.
CREATE TABLE vane_ga4_connections (
 site_id TEXT PRIMARY KEY REFERENCES vane_sites(id) ON DELETE CASCADE,
 generation TEXT NOT NULL, sealed_tokens TEXT NOT NULL,
 property TEXT, properties_json TEXT NOT NULL DEFAULT '[]',
 connected_by TEXT NOT NULL, connected_at INTEGER NOT NULL,
 last_sync INTEGER, next_sync INTEGER NOT NULL, last_error TEXT,
 lock_id TEXT, lock_until INTEGER
);
CREATE TABLE vane_ga4_oauth_states (
 state_hash TEXT PRIMARY KEY, site_id TEXT NOT NULL REFERENCES vane_sites(id) ON DELETE CASCADE,
 actor_id TEXT NOT NULL, session_hash TEXT NOT NULL,
 redirect_uri TEXT NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER
);
CREATE INDEX vane_ga4_oauth_expiry ON vane_ga4_oauth_states(expires_at);
